"""Check diagnostic-loader track boundaries using original generated bytes."""
import argparse
import hashlib
import json
from pathlib import Path
import subprocess
from pc286_loader import floppy, MAX_PAYLOAD


def sha(data):
    return hashlib.sha256(data).hexdigest()


def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--emulator',type=Path,required=True)
    p.add_argument('--output',type=Path,required=True)
    a=p.parse_args();exe=a.emulator.resolve(strict=True)
    root=a.output.resolve();root.mkdir(parents=True,exist_ok=False)
    try:
        floppy(bytes(MAX_PAYLOAD+1),0)
        raise AssertionError('oversized payload accepted')
    except ValueError:
        pass
    reports=[]
    # Cross the old third/fourth-track boundary and exercise the last byte.
    for length in (44*512,44*512+1,MAX_PAYLOAD):
        payload=bytearray(((i*37+i//251)&255) for i in range(length))
        payload[:6]=bytes.fromhex('b0a5e680ebfe')
        image=root/('payload-%d.img'%length);data=floppy(bytes(payload),0)
        image.write_bytes(data);observations=[]
        for offset in sorted(set((max(0,14*512-256),max(0,29*512-256),
                                  max(0,44*512-256),max(0,length-512)))):
            if offset>=length:continue
            size=min(512,length-offset)
            cmd=[str(exe),'--machine','pc286','--floppy',str(image),'--cycles','8000000',
                 '--timeout-ms','20000','--until-post','0xa5','--inspect',
                 hex(0x10000+offset)+':'+str(size)]
            result=subprocess.run(cmd,capture_output=True,text=True,timeout=25,
                                  creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
            if result.returncode:raise RuntimeError(result.stdout+result.stderr)
            response=json.loads(result.stdout)
            assert response['status']=='condition_met' and response['post']==0xa5
            assert bytes.fromhex(response['memory']['bytes'])==payload[offset:offset+size]
            observations.append({'offset':offset,'length':size,'command':cmd,'result':response})
        assert sha(image.read_bytes())==sha(data)
        reports.append({'length':length,'payload_sha256':sha(payload),'floppy_sha256':sha(data),
                        'observations':observations})
    # Mutate the final read to 14 sectors; an unwritten final sector must be
    # detected by the same inspection rather than accidentally passing.
    needle=bytes.fromhex('bb0058b80f02')
    assert data[:512].count(needle)==1
    mutant=bytearray(data);index=mutant[:512].index(needle);mutant[index+4]=14
    image=root/'short-final-read.img';image.write_bytes(mutant)
    offset=MAX_PAYLOAD-512
    cmd=[str(exe),'--machine','pc286','--floppy',str(image),'--cycles','8000000',
         '--timeout-ms','20000','--until-post','0xa5','--inspect',hex(0x10000+offset)+':512']
    result=subprocess.run(cmd,capture_output=True,text=True,timeout=25,
                          creationflags=getattr(subprocess,'CREATE_NO_WINDOW',0))
    if result.returncode:raise RuntimeError(result.stdout+result.stderr)
    response=json.loads(result.stdout)
    assert response['status']=='condition_met' and bytes.fromhex(response['memory']['bytes'])!=payload[offset:]
    assert sha(image.read_bytes())==sha(mutant)
    report={'status':'pass','emulator_sha256':sha(exe.read_bytes()),'cases':reports,
            'source_sha256':{p.name:sha(p.read_bytes()) for p in
                             (Path(__file__),Path(__file__).with_name('pc286_loader.py'))},
            'short_read_control':{'floppy_sha256':sha(mutant),'command':cmd,'result':response},
            'limits':'Diagnostic BIOS reads in BootHush only; no production loader or physical claim.'}
    (root/'report.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(report,indent=2))


if __name__=='__main__':main()
